def choose_move(observation):
    def sgn(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def first_pair(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2:
            return x[0], x[1]
        return None

    def pos(obj):
        p = first_pair(obj)
        if p is None:
            return None
        try:
            return int(p[0]), int(p[1])
        except Exception:
            return None

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def move_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def clip_move(m):
        dx = m[0] if isinstance(m, (list, tuple)) and len(m) > 0 else 0
        dy = m[1] if isinstance(m, (list, tuple)) and len(m) > 1 else 0
        return [sgn(dx), sgn(dy)]

    env = observation.get("environment_name", "resource_collection")
    me = pos(observation.get("self_position")) or (0, 0)
    opp = pos(observation.get("opponent_position")) or me
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return move_toward(me, opp)
        corners = []
        if isinstance(w, int) and isinstance(h, int) and w > 0 and h > 0:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        if corners:
            target = max(corners, key=lambda c: dist(c, opp))
            return move_toward(me, target)
        return [-sgn(opp[0] - me[0]), -sgn(opp[1] - me[1])]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best = None
        best_d = None
        for item in targets:
            t = pos(item)
            if t is None:
                continue
            d = dist(me, t)
            if best is None or d < best_d:
                best = t
                best_d = d
        if best is not None:
            return move_toward(me, best)
        return move_toward(me, opp)

    resources = observation.get("resources") or observation.get("resource_positions") or observation.get("items") or []
    best = None
    best_d = None
    for item in resources:
        t = pos(item)
        if t is None:
            continue
        d = dist(me, t)
        if best is None or d < best_d:
            best = t
            best_d = d

    if best is not None:
        return move_toward(me, best)

    return move_toward(me, opp)

